  mid fxi Ri Mi mdi cri si smi eni ki ei Y ->
  (getr Ri (PMK.reg 2) = Z_to_bv 64 (sp - 80) /\ getr Ri (PMK.reg 8) = Z_to_bv 64 (fb + 48) /\ getr Ri (PMK.reg 9) = Z_to_bv 64 (fb + 16)
   /\ getr Ri (PMK.reg 18) = Z_to_bv 64 (fb + 440))
  /\ (L5.writable RSEGS Mi (sp - 80) 80 /\ L5.u8_at RSEGS Mi (fb + 48 + 16) 0 /\ L5.writable RSEGS Mi (fb + 48 + 8) 1 /\ L5.img_clear Mi 65536 758952
      /\ L5.u64_at RSEGS Mi (fb + 440) 730848 /\ L5.defined Mi (sp - 80) 80)
  /\ (m_halted mdi = None /\ m_vm_lazy mdi = [])
  /\ (L5.u64_at RSEGS Mi (sp - 8) (bv_unsigned (getr R (PMK.reg 1))) /\ L5.u64_at RSEGS Mi (sp - 16) (bv_unsigned (getr R (PMK.reg 8)))
      /\ L5.u64_at RSEGS Mi (sp - 24) (bv_unsigned (getr R (PMK.reg 9))) /\ L5.u64_at RSEGS Mi (sp - 32) (bv_unsigned (getr R (PMK.reg 18)))
