(* [comment removed for export] *)
Lemma call_mkec (q v : Z) fxi Ri Mi mdi cri si smi eni ki ei Y :
  mid fxi Ri Mi mdi cri si smi eni ki ei Y ->
  getr Ri (PMK.reg 1) = Z_to_bv 64 q -> L5.ra_ok q -> getr Ri (PMK.reg 10) = Z_to_bv 64 (fb + 16) -> getr Ri (PMK.reg 11) = Z_to_bv 64 v -> 1 <= v <= 64 ->
  (forall fx2 R2 M2, regs_preserved Ri R2 -> mid fx2 R2 M2 mdi cri si smi eni ki true (w_ec true Y) ->
      srealizes RSEGS SCFG (PMSP.cfg RSEGS R2 q M2 mdi) K) ->
