(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma call_crun (T : Type) (pc h : Z) (args : T -> bvmap 5 word -> Z -> Prop) (MPf : T -> list Z -> st -> Prop) (F : T -> list Z -> st -> st)
    (a : T) (q : Z) fxi Ri Mi mdi cri si smi eni ki ei Y :
  PECS.crun_spec RSEGS CAD EE L HI P T pc h args MPf F -> 0 <= h <= 7 ->
  mid fxi Ri Mi mdi cri si smi eni ki ei Y ->
  getr Ri (PMK.reg 1) = Z_to_bv 64 q -> L5.ra_ok q ->
  args a Ri fb ->
  MPf a p Y -> s_bad (F a p Y) = false -> PESK.sp_hb P (s_hi (F a p Y)) ->
  (forall fx2 R2 M2 md2 cr2 s2 sm2 en2 k2 e2, regs_preserved Ri R2 -> mid fx2 R2 M2 md2 cr2 s2 sm2 en2 k2 e2 (F a p Y) ->
      srealizes RSEGS SCFG (PMSP.cfg RSEGS R2 q M2 md2) K) ->
  srealizes RSEGS SCFG (PMSP.cfg RSEGS Ri pc Mi mdi) K.
Proof.
  intros ES Hh MID Q1 Qok ARGS MPE NB' HB' CONT.
  destruct facts_ok as (RAok & Rra & Rsp & A16 & SLO & SHI & STOP & F1 & F2 & F3).
  destruct ENT as (_ & _ & _ & Rgp & Rtp & _). rewrite L5K.rl3 in Rgp. rewrite L5K.rl4 in Rtp.
  pose proof MID as (X2 & X8 & X9 & X18 & CS & C8 & C16 & C24 & C32 & C40 & C48 & STK & MB & MOKi & HHi & CPRE1 & STEP & EIMP & EK & DK & CK).
  pose proof MOKi as (Mh & Ml & Mm). pose proof STK as (_ & _ & _ & _ & SDEF).
  set (LB := PEC.owned si eni ki ++ LBX) in *.
  assert (BR : PMFR.brange L LB) by (apply (PMFR.brange_of_heap L HI HIok LB LB cri Mi _ HHi); apply incl_refl).
  assert (PINC : incl (PM.parser_own si) LB).
  { unfold LB, PEC.owned. intros x Hx. apply in_or_app. left. apply in_or_app. left. exact Hx. }
  assert (XINC : incl LBX (PM.parser_own si ++ LBX)) by (apply incl_appr; apply incl_refl).
  assert (SCR : 12288 <= PMSP.pm_scr h <= 26624) by (unfold PMSP.pm_scr; clear - Hh; lia).
  assert (STKc : L5C.stk (hl_sptop L) Mi (sp - 80) (PMSP.pm_scr h)).
  { apply (PMK.stk_call L Mi sp 28672 (sp - 80) (PMSP.pm_scr h) STK); [lia|lia|lia|]. replace (sp - 80) with (sp + (-5) * 16) by lia. rewrite Z.mod_add by lia. exact A16. }
  pose proof (PMPK.credit_le_keep cr cri _ _ CRED CK) as CLE.
  unfold PECS.crun_spec in ES.
  apply (ES SPM a fxi Ri Mi mdi K LBX cri (sp - 80) q fb cat p Y si str smi eni ki ei HHi MOKi K0).
  { unfold PMSP.entry. rewrite L5K.rl1, L5K.rl2, L5K.rl3, L5K.rl4. split; [exact Q1|]. split; [exact Qok|]. split; [exact X2|].
    split; [rewrite (CS 3%nat) by (cbn; tauto); exact Rgp|]. split; [rewrite (CS 4%nat) by (cbn; tauto); exact Rtp|]. exact STKc. }
  { unfold PMSP.frame_ok. cbn [pa_frame CAD PeCLayoutS.CADDR_S]. split; [lia|]. split; [lia| exact F3]. }
  { exact ARGS. }
  { exact CPRE1. }
  { exact INCS. }
  { exact POK. }
  { exact MPE. }
  { exact NB'. }
  { exact HB'. }
  { exact CLE. }
  intros fx2 R2 M2 md2 s2 sm2 en2 k2 e2 cr2 RP2 CPRE2 STEP2 EIMP2 HP2 CK2 MB2 HH2.
  pose proof (PMK.ek_of_hpres L LBX (sp - 80) (PMSP.pm_scr h) (PEC.W_crun CAD EE fb) Mi M2 HP2) as EK2.
  assert (WCE : forall a1, PMK.inW (PEC.W_crun CAD EE fb) a1 -> (fb + 16 <= a1 < fb + 676) \/ (0xc9640 <= a1 < 0xeb2a8)).
  { intros a1 (r0 & Hin & Hr). unfold PEC.W_crun, PMSP.W_run, PMSP.W_srcf, PMSP.err_W, PMSP.o_src, PMSP.o_tb, PMSP.o_vec, PMSP.o_ec, PMSP.o_is, PMSP.o_p, PMSP.o_v, PESK.o_sink in Hin.
    cbn [pa_off_p pa_off_is pa_off_ec pa_off_v pe_off_sink pa_errcat_guard pa_atexit CAD EE PeCLayoutS.CADDR_S PeCLayoutS.EADDR_S app] in Hin. unfold L5.in_rng in Hr.
    repeat (destruct Hin as [<-|Hin]; [cbn [fst snd] in Hr; lia|]). destruct Hin. }
  assert (SC4 : 0 <= PMSP.pm_scr h) by (clear - SCR; lia).
  assert (CKEEP : forall a1 v, sp - 48 <= a1 -> a1 + 8 <= sp -> L5.u64_at RSEGS Mi a1 v -> L5.u64_at RSEGS M2 a1 v).
  { intros a1 v Ha1 Ha2 Hc. apply (PMFR.u64_keep RSEGS L KL LBX (sp - 80) (PMSP.pm_scr h) _ Mi M2 EK2 STKc SC4); [lia|lia| | exact Hc].
    intros i Hi I. apply WCE in I. clear - Hi I F1 SLO STOP Ha1 Ha2. lia. }
  apply (CONT fx2 R2 M2 md2 cr2 s2 sm2 en2 k2 e2 RP2). unfold mid.
  split; [rewrite (PMK.cs_of_preserved Ri R2 2%nat RP2) by PMK.inl; exact X2|].
  split; [rewrite (PMK.cs_of_preserved Ri R2 8%nat RP2) by PMK.inl; exact X8|].
  split; [rewrite (PMK.cs_of_preserved Ri R2 9%nat RP2) by PMK.inl; exact X9|].
  split; [rewrite (PMK.cs_of_preserved Ri R2 18%nat RP2) by PMK.inl; exact X18|].
