  split; [apply CKEEP; [lia|lia|exact C8]|]. split; [apply CKEEP; [lia|lia|exact C16]|]. split; [apply CKEEP; [lia|lia|exact C24]|].
  split; [apply CKEEP; [lia|lia|exact C32]|]. split; [apply CKEEP; [lia|lia|exact C40]|]. split; [apply CKEEP; [lia|lia|exact C48]|].
  split; [apply (PMK.stk_after RSEGS L KL LBX Mi M2 sp 28672 (sp - 80) (PMSP.pm_scr h) _ STK HP2); lia|].
  split; [exact (L5C.model_but_vm_trans _ _ _ MB MB2)|].
  split; [exact (PMFR.model_ok_but_vm mdi md2 MOKi MB2)|].
  split; [exact HH2|].
  split; [exact CPRE2|].
  split; [exact (PMPK.src_step_trans _ _ _ _ _ _ STEP STEP2)|].
  split; [intros E0; exact (EIMP2 (EIMP E0))|].
  split.
  { apply (PMK.ek_trans L LBX sp 28672 _ M Mi M2 EK).
    apply (PMK.ek_callee_in' RSEGS L KL LBX LBX sp 28672 (sp - 80) (PMSP.pm_scr h) _ _ Mi M2 HP2 (incl_refl _));
      [lia|lia| unfold hl_ceil; lia| lia| exact (PMFR.brange_hi L LBX (PMFR.brange_incl L LBX LB BR ltac:(unfold LB; apply incl_appr; apply incl_refl)))|].
    intros a1 I. right. exact I. }
  split.
  { apply (PMK.dk_trans L LBX sp 28672 M Mi M2 DK). apply (PMK.dk_callee L LBX LBX sp 28672 (sp - 80) (PMSP.pm_scr h) _ Mi M2 HP2 (incl_refl _)); lia. }
  unfold PMSP.credit_keep in CK, CK2 |- *. clear - CK CK2. lia.
Qed.

